30	function neighborsOf([x, y]: Cell): Cell[] {
31	  const neighbors: Cell[] = [];
32	  for (let dx = -1; dx <= 1; dx++) {
33	    for (let dy = -1; dy <= 1; dy++) {
34	      if (dx !== 0 || dy !== 0) {
35	        neighbors.push([x + dx, y + dy]);
36	      }
37	    }
38	  }
39	  return neighbors;
40	}
