48	function deadNeighborsOfLiveCells(liveCells: Cell[]): Cell[] {
49	  const allNeighbors = liveCells.flatMap(neighborsOf);
50	  const deadNeighbors = allNeighbors.filter((cell) => !contains(liveCells, cell));
51	  return uniqueCells(deadNeighbors);
52	}
